contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address receiver) public {
        uint cBefore = address(c).balance;
        uint rBefore = receiver.balance;
        // amount is fixed to 0, a valid input for the rule
        c.sendTo(receiver, 0); if (__ESBMC_reverted()) return;
        uint cAfter = address(c).balance;
        uint rAfter = receiver.balance;
        assert(cAfter == cBefore && rAfter == rBefore);
    }

    receive() external payable {}
}

